    raise ValueError("Playlist 'My R&B' was not found.")

playlist_id = playlist["id"]
artist_ids = set()
offset = 0

while True:
    tracks_response = requests.get(
        f"{BASE_URL}/playlists/{playlist_id}/tracks",
        headers=headers,
        params={"limit": 100, "offset": offset},
    )
