import requests

headers = {
    "Authorization": "Bearer YOUR_ACCESS_TOKEN"
}

response = requests.get(
    "https://api.spotify.com/v1/me/playlists",
    headers=headers
)
response.raise_for_status()

playlists = response.json().get("items", [])
playlist = next((item for item in playlists if item.get("name") == "My R&B"), None)

if playlist:
    response = requests.get(
        f"https://api.spotify.com/v1/playlists/{playlist['id']}/tracks",
        headers=headers
    )
    response.raise_for_status()

    artist_ids = {
        artist["id"]
        for item in response.json().get("items", [])
        for artist in item.get("track", {}).get("artists", [])
        if artist.get("id")
    }

    if artist_ids:
        response = requests.put(
            "https://api.spotify.com/v1/me/following",
            headers=headers,
            params={"type": "artist", "ids": ",".join(artist_ids)}
        )
        response.raise_for_status()

